	@Test
	void databaseExactOneRowRootEvidenceStillSuppressesTheScalarCertifier() {
		AtomicInteger certifications = new AtomicInteger();
		class Exact implements PackedCostModel, PackedRootCardinalityCertifier {
			@Override
			public double estimateRows(PackedQueryView query, int relationId) {
				return Double.NaN;
			}

			@Override
			public PackedCostSession openSession(PackedQueryView query) {
				return new PackedCostSession() {
					private final FrontierStateArena arena = new FrontierStateArena(64L * 1024L);
					// Real query-local summary handle for the Group's semantic singleton; no store/value authority.
					private final EvidenceStateRef singleton = arena.append(FrontierLayout.of("count"),
							EvidenceStateSummary.exact(1D));

					@Override
					public void estimateLeaf(int relationId, PackedCostContext context, PackedCostEstimate output) {
						boolean group = query.operatorTag(relationId) == PackedRelOp.GROUP;
						output.setRows(group ? 1D : 0D, 1D);
						output.setEvidenceStateId(group ? singleton.stateId() : 0);
						output.setEvidenceGuarantee(group ? singleton.summary().guarantee() : null);
						output.setEvidenceDisposition(group ? FrontierStateDisposition.BOUND_ONLY : null);
					}

					@Override
					public void appendFactor(int relationId, PackedCostContext context, PackedCostEstimate output) {
						estimateLeaf(relationId, context, output);
					}

					@Override
					public void refineOperator(int relationId, PackedCostContext context, PackedCostEstimate output) {
						estimateLeaf(relationId, context, output);
					}

					@Override
					public FrontierEvidenceBundle detachEvidence(int[] evidenceStateIds) {
						return arena.exportEvidence(evidenceStateIds);
					}

					@Override
					public void close() {
						arena.close();
					}
				};
			}

			@Override
			public double certifyRootRows(TupleExpr selectedPlan, double packedRows) {
				certifications.incrementAndGet();
				return Double.POSITIVE_INFINITY;
			}
		}
		PackedPlanningResult result = PackedCascadesPlanner.optimize(group(), OptimizationGoal.root(), new Exact());
		assertEquals(1D, result.outputRows());
		assertEquals("database_exact",
				result.selectedPlan().getStringMetricPlanned("plannedFrontierGuarantee"));
		assertEquals(0, certifications.get(), "existing exact-evidence precedence must suppress this invalid hook");
	}

	private static void assertGroupEvents(PackedCostingTrace trace, PackedQuery query) {
		int operatorEvents = 0;
		for (int event = 1; event <= trace.eventCount(); event++) {
			if ((trace.phase(event) == PackedCostingPhase.LEAF || trace.phase(event) == PackedCostingPhase.OPERATOR)
					&& query.relOperator(trace.relationId(event)) == PackedRelOp.GROUP
					&& trace.prefixRelationCount(event) == 0) {
				if (trace.phase(event) == PackedCostingPhase.OPERATOR) {
					operatorEvents++;
				}
				assertEquals(1D, trace.prefixRows(event));
				assertEquals(1D, trace.outputRows(event));
				assertNull(trace.guarantee(event));
			}
		}
		assertTrue(operatorEvents > 0, "the retained trace must reach canonical Group refinement");
	}

	private static PackedCostModel zeroGroupModel() {
		return new PackedCostModel() {
			@Override
			public double estimateRows(PackedQueryView query, int relationId) {
				return Double.NaN;
			}

			@Override
			public void estimate(PackedQueryView query, int relationId, PackedCostContext context,
					PackedCostEstimate output) {
				output.setRows(0D, 5D);
				if (query.materializeRelation(relationId) instanceof Group) {
					output.setEvidenceGuarantee(EvidenceGuarantee.DATABASE_EXACT);
				}
			}

			@Override
			public void refineOperator(PackedQueryView query, int relationId, PackedCostContext context,
					PackedCostEstimate output) {
				if (query.materializeRelation(relationId) instanceof Group) {
					output.setRows(0D, 7D);
					output.setEvidenceGuarantee(EvidenceGuarantee.DATABASE_EXACT);
				}
			}
		};
	}

	private static Group group() {
		return new Group(new EmptySet(), List.of(),
				List.of(new GroupElem("count", new Count(Var.of("s"), true))));
	}
